// Lê a página de vendas: vale a revisada (se a revisora falhar, a da redatora; se as duas falharem, textos padrão do plano).
// Trava: promessa de ganho/resultado e R$ que não é o preço saem; garantia só se o produtor deu uma.
const V = $('🧩 Confere o pedido').first().json, R = $('🧩 Aplica a revisão').first().json, plano = $('🧩 Lê o plano').first().json.plano;
let a = null, rv = null;
try { a = parseJSON($('🤖 Redatora de vendas').first().json.output); } catch (e) {}
try { rv = parseJSON($('🤖 Revisora de vendas').first().json.output); } catch (e) {}
const x = rv && rv.titulo ? rv : a && a.titulo ? a : {};
const valores = new Set(V.dados.venda.preco ? [Math.round(V.dados.venda.preco * 100)] : []);
const trava = [];
const G = (t, n, onde) => cuGuarda(cuL(t, n), valores, 'página de vendas (' + onde + ')', trava);
const lista = (v, n, max) => (Array.isArray(v) ? v : []).map(i => G(i, n, 'lista')).filter(Boolean).slice(0, max);
const vendas = {
  titulo: G(x.titulo, 90, 'título') || plano.titulo, subtitulo: G(x.subtitulo, 200, 'subtítulo') || plano.subtitulo,
  para_quem: lista(x.para_quem, 140, 5).length ? lista(x.para_quem, 140, 5) : plano.para_quem,
  aprender: lista(x.aprender, 140, 8).length ? lista(x.aprender, 140, 8) : R.modulos.flatMap(m => m.aulas.map(au => au.titulo)).slice(0, 8),
  sobre_instrutor: G(x.sobre_instrutor, 400, 'instrutor') || V.dados.instrutor.bio,
  faq: (Array.isArray(x.faq) ? x.faq : []).filter(f => f && typeof f === 'object').map(f => ({ p: cuL(f.p, 140), r: G(f.r, 400, 'dúvidas') })).filter(f => f.p && f.r).slice(0, 6),
  cta: cuL(x.cta, 40) || (V.dados.venda.modo === 'pago' ? 'Quero me inscrever' : 'Quero acessar grátis'),
  garantia_texto: V.dados.venda.garantia ? (G(x.garantia_texto, 200, 'garantia') || V.dados.venda.garantia) : '',
};
const problemas = rv && Array.isArray(rv.problemas) ? rv.problemas.map(p => cuT(p, 200)).filter(p => p && !/\bok\b|está corret|estão corret|nenhum problema|sem altera/i.test(p)).slice(0, 4) : [];
return [{ json: { vendas, problemas, trava } }];

// Junta as imagens que a IA desenhou (uma por pedido, na mesma ordem) num pedido só para a oficina guardar na pasta do evento.
const V = $('🧩 Confere o pedido').first().json;
const pedidos = $('🧩 Lista as imagens').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const imagens = [], falhas = [];
pedidos.forEach((p, i) => {
  const r = res[i] || {}, b64 = r.data && r.data[0] && r.data[0].b64_json;
  if (b64) imagens.push({ nome: p.nome, b64 }); else falhas.push({ nome: p.nome, erro: String((r.error && (r.error.message || r.error)) || r.message || 'sem imagem').slice(0, 160) });
});
return [{ json: { corpo: JSON.stringify({ area: 'cursos', deck: V.id, imagens }), geradas: imagens.length, falhas } }];

// Monta o pedido da revisora das imagens (IA com visão): cada miniatura com o pedido que gerou a imagem.
const V = $('🧩 Confere o pedido').first().json;
const g = $('🛠️ Oficina: guarda as imagens').first().json || {};
const pedidos = $('🧩 Lista as imagens').all().map(i => i.json);
const guardadas = Array.isArray(g.imagens) ? g.imagens : [];
const conteudo = [{ type: 'text', text: `Você revisa imagens geradas por IA para um curso online sobre "${V.dados.tema}" (capa do curso e abertura de cada módulo).
Reprove (ok=false) se tiver: texto, letras ou números legíveis (até em telas, quadros, livros ou placas); logotipo ou marca; rosto ou mão deformados; objeto derretido ou sem sentido; algo que não combina com o assunto; conteúdo impróprio.
PODE passar: pessoa de longe, de costas ou desfocada; pequenos defeitos que ninguém nota. Refazer custa 1 minuto: só reprove o que estragaria o curso.
RETORNE SOMENTE JSON: {"imagens":[{"nome":"img-01","ok":true,"problema":"o que está errado, em poucas palavras"}]}` }];
for (const im of guardadas) {
  const p = pedidos.find(x => x.nome === im.nome) || {};
  conteudo.push({ type: 'text', text: `IMAGEM ${im.nome} (${p.uso || ''}) — pedido: ${String(p.prompt || '').slice(0, 300)}` });
  conteudo.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + im.mini } });
}
return [{ json: { corpo: JSON.stringify({ model: 'antigravity/gemini-3-flash', max_tokens: 1500, temperature: 0.1, messages: [{ role: 'user', content: conteudo }] }), qtd: guardadas.length } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê a revisão das imagens. Refaz uma vez: a imagem reprovada (com o defeito no pedido) e a que não veio.
const pedidos = $('🧩 Lista as imagens').all().map(i => i.json);
const g = $('🛠️ Oficina: guarda as imagens').first().json || {};
const guardadas = (Array.isArray(g.imagens) ? g.imagens : []).map(x => x.nome);
const r = $input.first().json || {};
let v = null;
try { v = parseJSON(r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content); } catch (e) {}
const notas = v && Array.isArray(v.imagens) ? v.imagens : [];
const refazer = [];
for (const p of pedidos) {
  const nota = notas.find(x => x && x.nome === p.nome);
  if (!guardadas.includes(p.nome)) refazer.push({ ...p, motivo: 'não veio', nome: p.nome + '-r1' });
  else if (nota && nota.ok === false) refazer.push({ ...p, motivo: String(nota.problema || 'defeito').slice(0, 120), nome: p.nome + '-r1',
    prompt: p.prompt + ' Avoid this problem from the previous attempt: ' + String(nota.problema || 'visual defects').slice(0, 120) + '.' });
}
const reprovadas = notas.filter(x => x && x.ok === false).map(x => ({ nome: x.nome, problema: String(x.problema || '').slice(0, 120) }));
if (!refazer.length) return [{ json: { refazer: false, viu: !!v, reprovadas } }];
return refazer.map(x => ({ json: { ...x, refazer: true, viu: !!v, reprovadas } }));

// Junta as imagens que a IA desenhou (uma por pedido, na mesma ordem) num pedido só para a oficina guardar na pasta do evento.
const V = $('🧩 Confere o pedido').first().json;
