.s:after{content:"";position:absolute;right:-160px;top:-160px;width:620px;height:620px;border-radius:50%;background:${c.suave}}
.s>*{position:relative;z-index:1}.mod{font:700 34px Inter,sans-serif;letter-spacing:4px;text-transform:uppercase;color:${c.forte}}
.capa{background:${c.escuro};color:#fff}.capa:after{background:${cuMistura(c.escuro, '#FFFFFF', 0.08)}}.capa .mod{color:${cuMistura(c.cor, '#FFFFFF', 0.55)}}
h1{font:800 104px Montserrat,sans-serif;line-height:1.05;max-width:1500px}h2{font:800 78px Montserrat,sans-serif;line-height:1.1;max-width:1550px}
p{font-size:40px;line-height:1.45;max-width:1450px;color:inherit;opacity:.85}.inst{font-size:32px;opacity:.75}
.num{width:120px;height:120px;border-radius:50%;background:${c.forte};color:${c.tinta};display:grid;place-items:center;font:800 64px Montserrat,sans-serif}
