</style></head><body>${slides.join('')}</body></html>`;
}

// Monta o curso: plano + aulas revisadas + quizzes + página de vendas + imagens aprovadas + cores + chaves dos avisos no celular (VAPID).
const crypto = require('crypto');
const tenta = f => { try { return f(); } catch (e) { return null; } };
const V = $('🧩 Confere o pedido').first().json, R = $('🧩 Aplica a revisão').first().json, S = $('🧩 Lê as vendas').first().json, plano = $('🧩 Lê o plano').first().json.plano;
const prim = tenta(() => $('🛠️ Oficina: guarda as imagens').first().json.imagens) || [];
const ref = tenta(() => $('🛠️ Oficina: guarda as refeitas').first().json.imagens) || [];
const reprovadas = (tenta(() => $('🧩 Lê a revisão das imagens').first().json.reprovadas) || []).map(x => x.nome);
const img = nome => { const r1 = ref.find(x => x.nome === nome + '-r1'); if (r1) return r1.arquivo; const p = prim.find(x => x.nome === nome); return p && !reprovadas.includes(nome) ? p.arquivo : ''; };
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
const jwk = privateKey.export({ format: 'jwk' }), pub = publicKey.export({ format: 'jwk' });
const modulos = R.modulos.map(m => ({ n: m.n, titulo: m.titulo, objetivo: m.objetivo, imagem: img('img-0' + (m.n + 1)), aulas: m.aulas, quiz: m.quiz }));
const minutos = modulos.reduce((s, m) => s + m.aulas.reduce((x, a) => x + a.minutos, 0), 0);
const palavras = V.dados.instrutor.nome.normalize('NFD').replace(/[̀-ͯ]/g, '').split(/[^A-Za-z]+/).filter(Boolean);
const curso = {
  id: V.id, chave: V.chave, versao: 1, criado_em: V.criado_em, tema: V.dados.tema, titulo: plano.titulo, subtitulo: plano.subtitulo, promessa: plano.promessa,
  publico: V.dados.publico, nivel: V.dados.nivel, prerequisitos: plano.prerequisitos, projeto_final: plano.projeto_final, instrutor: V.dados.instrutor,
  modulos, horas: Math.max(1, Math.round(minutos / 60 * 10) / 10), venda: V.dados.venda, vendas: S.vendas, cores: cuTokens(V.op.cor), op: V.op,
  imagens: { capa: img('img-01') }, iniciais: (palavras.length > 1 ? palavras[0][0] + palavras[1][0] : (palavras[0] || 'C').slice(0, 2)).toUpperCase(),
  vapid: { publica: b64u(Buffer.concat([Buffer.from([4]), unb(pub.x), unb(pub.y)])), privada: { kty: 'EC', crv: 'P-256', d: jwk.d, x: jwk.x, y: jwk.y } },
  videos: { estado: V.op.videos ? 'na_fila' : 'sem_video', prontos: 0 },
