</style></head><body><div class="w">
<div class="card"><h1>🎓 ${E(c.titulo)}</h1><p class="sub">${N.aulas} aulas · ${String(c.horas).replace('.', ',')} h · ${c.venda.modo === 'pago' ? 'pago: ' + E(cuBRL(c.venda.preco)) : 'grátis com cadastro'} · vídeo-aulas: ${N.videos}/${N.aulas}${c.videos && c.videos.estado === 'na_fila' ? ' (sendo feitas)' : ''}</p>
<div class="duas" style="margin-top:10px"><div><b>Página de vendas</b> (divulgue)<code class="link">${E(links.vendas)}</code><div class="bts"><a class="btn sec" href="${E(links.vendas)}" target="_blank" rel="noopener">👁️ Abrir</a><button class="btn sec" type="button" data-copiar="${E(links.vendas)}">📋 Copiar</button></div></div>
<div><b>Área do aluno</b> (entra com o código)<code class="link">${E(links.aluno)}</code><div class="bts"><a class="btn sec" href="${E(links.aluno)}" target="_blank" rel="noopener">👁️ Abrir</a><button class="btn sec" type="button" data-copiar="${E(links.aluno)}">📋 Copiar</button></div></div></div></div>
<div class="kpis"><div class="kpi"><small>Alunos com acesso</small><b>${N.alunos}</b><span>${N.pedidos} pediram para entrar</span></div><div class="kpi"><small>Ativos (7 dias)</small><b>${N.ativos_7d}</b><span>abriram o curso</span></div>
<div class="kpi"><small>Progresso médio</small><b>${N.media_pct}%</b><span>das aulas</span></div><div class="kpi"><small>Concluíram</small><b>${N.concluiram}</b><span>todas as aulas</span></div><div class="kpi"><small>Certificados</small><b>${N.certificados}</b><span>emitidos</span></div></div>
<div class="card"><h2>👥 Alunos</h2><div class="filtros"><input type="search" id="filtro" placeholder="Filtrar por nome, código, contato…" aria-label="Filtrar alunos"><button class="btn sec" id="csv" type="button">⬇️ CSV</button></div>
<div class="rol"><table id="t-alunos"><thead></thead><tbody></tbody></table></div></div>
<div class="duas"><div class="card"><h2>✅ Liberar um aluno</h2><p class="sub">Recebeu o pagamento? Gere o código e mande pelo WhatsApp.</p>
<form id="liberar"><div class="filtros" style="margin-top:8px"><input id="l-nome" placeholder="Nome do aluno" maxlength="60" aria-label="Nome do aluno"><input id="l-zap" placeholder="WhatsApp (opcional)" inputmode="tel" aria-label="WhatsApp do aluno"></div>
<button class="btn" type="submit">🔑 Gerar código</button><p class="erro" id="l-erro" role="alert"></p></form><div class="ok" id="lib-res" hidden role="status"></div></div>
<div class="card"><h2>✨ Análise do curso (IA)</h2><p class="sub">Onde os alunos param e as perguntas mais erradas; a revisora confere todos os números.</p><div class="bts"><button class="btn" id="bt-ia" type="button">✨ Analisar com IA</button></div><div id="ia" role="status" aria-live="polite"></div></div></div>
<div class="card"><h2>🎬 Vídeo-aulas</h2><ul class="lista">${dados.aulas.map(a => `<li>Aula ${a.n}: ${E(a.titulo)} — ${a.video ? `<a href="${E(a.video)}" target="_blank" rel="noopener">▶️ ver</a>` : a.erro ? '⚠️ ' + E(a.erro) : c.op.videos ? '⏳ sendo feita' : 'sem vídeo'}</li>`).join('')}</ul></div>
${(c.revisao.problemas || []).length || (c.revisao.trava || []).length ? `<div class="card"><h2>🔍 O que a revisão ajustou</h2><ul class="lista">${[...(c.revisao.problemas || []), ...(c.revisao.trava || [])].slice(0, 12).map(p => `<li>${E(p)}</li>`).join('')}</ul></div>` : ''}
</div><script>(${app.toString()})(${JSON.stringify(dados).replace(/</g, '\\u003c')});</script></body></html>`;
return [{ json: { codigo: 200, tipo: 'text/html; charset=UTF-8', html } }];

let b = $('🔔 Pedido do produtor (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
return [{ json: { ...b, id: String(b.id || '').replace(/[^a-z0-9-]/g, '').slice(0, 64) || 'nenhum', chave: String(b.chave || ''), acao: String(b.acao || ''),
  token: String(b.token || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8), base: String($('🔔 Pedido do produtor (POST)').first().json.webhookUrl || '').split('/webhook/')[0] } }];

// Regras do curso online (as mesmas na criação, na área do aluno, no certificado e no painel do produtor).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const cuT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const cuL = (v, max) => cuT(v, max).replace(/[<>{}]/g, '');
const cuTP = (v, max) => String(v ?? '').replace(/\r/g, '').split(/\n{2,}/).map(p => p.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n\n').replace(/[<>{}]/g, '').slice(0, max);
const cuEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const cuBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const cuNum = v => {
  if (typeof v === 'number') return isFinite(v) && v >= 0 ? Math.round(v * 100) / 100 : null;
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 && n < 1000000 ? Math.round(n * 100) / 100 : null;
};
const cuHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const cuLum = h => cuHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const cuContraste = (a, b) => { const x = cuLum(a), y = cuLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const cuMistura = (a, b, k) => { const x = cuHex(a), y = cuHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores do curso a partir da cor do produtor (contraste garantido: destaque no branco e texto do botão)
function cuTokens(cor) {
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : '#3F51B5';
  let forte = c;
  for (let i = 0; i < 16 && cuContraste(forte, '#FFFFFF') < 4.5; i++) forte = cuMistura(forte, '#000000', 0.12);
  const tinta = cuContraste('#FFFFFF', forte) >= 4.5 ? '#FFFFFF' : '#111111';
  return { cor: c, forte, botao: forte, tinta, fundo: cuMistura(c, '#FFFFFF', 0.95), suave: cuMistura(c, '#FFFFFF', 0.87), linha: cuMistura(c, '#FFFFFF', 0.72), escuro: cuMistura(forte, '#000000', 0.55) };
}
// trava: promessa de ganho, resultado garantido ou R$ que não é o preço do produtor sai da frase
const CU_PROMESSA = /(ganh\w*|fatur\w*|lucr\w*|renda)\s+(de\s+)?(at[eé]\s+)?r\$|fique\s+rico|ficar\s+rico|dinheiro\s+f[aá]cil|renda\s+extra\s+garantid|resultado\s+garantid|garantimos\s+(que|o\s+seu)|100%\s+garantid|sem\s+esfor[cç]o|em\s+\d+\s+dias\s+voc[eê]\s+(vai|ir[aá])\s+(ganhar|faturar)/i;
function cuGuarda(txt, valores, onde, problemas) {
  return String(txt || '').split(/\n{2,}/).map(par => par.split(/(?<=[.!?…])\s+/).filter(f => {
    const vs = (f.match(/R\$\s?\d[\d.]*(?:,\d{1,2})?/g) || []).map(x => Math.round(cuNum(x) * 100)).filter(n => !valores.has(n));
    const prom = CU_PROMESSA.test(f);
    if ((vs.length || prom) && problemas) problemas.push(`${onde}: tirei "${cuT(f, 90)}" (${prom ? 'promessa de ganho/resultado' : 'valor que não é o seu preço'})`);
    return !vs.length && !prom;
  }).join(' ').trim()).filter(Boolean).join('\n\n');
}
// aula escrita pela professora (ou revisada) no formato do curso; sem falas, a narração sai do próprio texto
function cuAula(x, base) {
  x = x && typeof x === 'object' ? x : {};
  const secoes = (Array.isArray(x.secoes) ? x.secoes : []).map(s => ({ titulo: cuL(s && s.titulo, 80), texto: cuTP(s && s.texto, 900) })).filter(s => s.texto).slice(0, 4);
  const pontos = (Array.isArray(x.pontos) ? x.pontos : []).map(p => cuL(p, 110)).filter(Boolean).slice(0, 3);
  const a = { ...base, intro: cuTP(x.intro, 600), secoes, exemplo: cuTP(x.exemplo, 700), pontos, exercicio: cuTP(x.exercicio, 500),
    minutos: Math.max(3, Math.min(30, parseInt(x.minutos, 10) || 8)), video: '', capa: '', imagem: '' };
  let falas = (Array.isArray(x.falas) ? x.falas : []).map(f => cuT(f, 420)).filter(Boolean).slice(0, 5);
  if (falas.length < 2) falas = [a.intro, ...a.secoes.map(s => cuT(s.texto, 300)), a.exercicio].filter(Boolean).slice(0, 5);
  return { ...a, falas };
}
// quiz do módulo: só pergunta com 4 opções e a certa entre elas
function cuQuiz(q) {
  return (Array.isArray(q) ? q : []).filter(x => x && typeof x === 'object').map(x => ({ p: cuL(x.p, 220), opcoes: (Array.isArray(x.opcoes) ? x.opcoes : []).map(o => cuL(o, 140)).slice(0, 4),
    certa: Number.isInteger(x.certa) ? x.certa : parseInt(x.certa, 10), explicacao: cuL(x.explicacao, 260) }))
    .filter(x => x.p && x.opcoes.length === 4 && x.opcoes.every(Boolean) && x.certa >= 0 && x.certa <= 3).slice(0, 6);
}
// código de acesso do aluno: 8 letras/números sem os que confundem (0/O, 1/I/L)
function cuCodigo() { const A = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789', b = require('crypto').randomBytes(8); return Array.from(b, x => A[x % A.length]).join(''); }
const cuAulas = curso => curso.modulos.flatMap(m => m.aulas);
// progresso do aluno: aulas feitas, quiz de cada módulo (≥ 70% passa), próxima aula, se já pode tirar o certificado
function cuProgresso(curso, al) {
  const aulas = cuAulas(curso), feitas = aulas.filter(a => al.feitas && al.feitas[a.n]).length;
  // módulo sem quiz (a IA não fez perguntas válidas) não trava o certificado
  const quizzes = curso.modulos.map(m => { const q = (al.quizzes || {})[m.n]; return { m: m.n, nota: q ? q.nota : null, passou: !m.quiz.length || !!(q && q.nota >= 70) }; });
  const proxima = (aulas.find(a => !(al.feitas && al.feitas[a.n])) || aulas[aulas.length - 1] || {}).n;
  const pct = aulas.length ? Math.round(feitas / aulas.length * 100) : 0;
  return { feitas, total: aulas.length, pct, quizzes, proxima, pode_certificado: feitas === aulas.length && quizzes.every(q => q.passou) };
}
// corrige o quiz no servidor (a página não sabe a resposta certa)
function cuCorrige(quiz, respostas) {
  const r = Array.isArray(respostas) ? respostas : [];
  const itens = quiz.map((q, i) => ({ i, marcou: Number.isInteger(r[i]) ? r[i] : -1, certa: q.certa, acertou: r[i] === q.certa, explicacao: q.explicacao }));
  const acertos = itens.filter(x => x.acertou).length;
  return { acertos, total: quiz.length, nota: quiz.length ? Math.round(acertos / quiz.length * 100) : 0, itens };
}
// slides da vídeo-aula (1920×1080, um por página no PDF): abertura, um por ponto-chave, exercício; as falas da IA narram cada um
function cuSlidesHtml(curso, m, a) {
  const c = curso.cores, E = cuEsc;
  const pts = (a.pontos || []).slice(0, 3);
  const slides = [
    `<section class="s capa"><span class="mod">Módulo ${m.n} · Aula ${a.n}</span><h1>${E(a.titulo)}</h1><p>${E(a.objetivo)}</p><span class="inst">${E(curso.instrutor.nome)} · ${E(curso.titulo)}</span></section>`,
    ...pts.map((p, i) => `<section class="s ponto"><span class="num">${i + 1}</span><h2>${E(p)}</h2>${a.secoes[i] ? `<p>${E(cuT(a.secoes[i].texto, 260))}</p>` : ''}</section>`),
    `<section class="s fim"><span class="mod">Para praticar</span><h2>${E(cuT(a.exercicio, 220))}</h2><p>Próximo passo: marque a aula como concluída e siga para a próxima.</p></section>`,
  ];
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><style>
@page{size:1920px 1080px;margin:0}*{box-sizing:border-box;margin:0;padding:0}
body{font-family:Inter,'Noto Color Emoji',sans-serif;color:#1B1B1F}
.s{width:1920px;height:1080px;page-break-after:always;padding:120px 150px;display:flex;flex-direction:column;justify-content:center;gap:36px;position:relative;overflow:hidden;background:${c.fundo}}
.s:after{content:"";position:absolute;right:-160px;top:-160px;width:620px;height:620px;border-radius:50%;background:${c.suave}}
.s>*{position:relative;z-index:1}.mod{font:700 34px Inter,sans-serif;letter-spacing:4px;text-transform:uppercase;color:${c.forte}}
.capa{background:${c.escuro};color:#fff}.capa:after{background:${cuMistura(c.escuro, '#FFFFFF', 0.08)}}.capa .mod{color:${cuMistura(c.cor, '#FFFFFF', 0.55)}}
h1{font:800 104px Montserrat,sans-serif;line-height:1.05;max-width:1500px}h2{font:800 78px Montserrat,sans-serif;line-height:1.1;max-width:1550px}
p{font-size:40px;line-height:1.45;max-width:1450px;color:inherit;opacity:.85}.inst{font-size:32px;opacity:.75}
.num{width:120px;height:120px;border-radius:50%;background:${c.forte};color:${c.tinta};display:grid;place-items:center;font:800 64px Montserrat,sans-serif}
.fim{background:${c.suave}}
</style></head><body>${slides.join('')}</body></html>`;
}

// Ações do produtor (com a chave do painel): liberar um aluno novo (gera o código e a mensagem de WhatsApp), liberar quem pediu (interesse) e pedir a análise da IA.
const P = $('🧩 Lê o pedido do produtor').first().json;
let c = null;
try { c = JSON.parse($('📖 Lê o curso (produtor)').first().json.curso || 'null'); } catch (e) {}
const responde = (codigo, corpo) => [{ json: { rota: 'responder', codigo, resposta: JSON.stringify(corpo), sets: [] } }];
if (!c) return responde(404, { ok: false, erro: 'Curso não encontrado.' });
if (!P.chave || P.chave !== c.chave) return responde(403, { ok: false, erro: 'Chave errada. Use o link do painel que apareceu quando você criou o curso.' });
const alunos = Object.entries($('🗂️ Lê os alunos (produtor)').first().json || {}).filter(([k]) => k.startsWith(`cua:${c.id}:`)).map(([k, v]) => { try { return JSON.parse(v); } catch (e) { return null; } }).filter(Boolean);
const area = `${P.base}/webhook/curso/${c.id}/aluno`;
const msg = (nome, token) => `Olá, ${String(nome).split(' ')[0]}! Seu acesso ao curso "${c.titulo}" está liberado. 🎉\nEntre por aqui: ${area}?a=${token}\nSeu código: ${token}`;
const libera = al => {
  al.liberado = true; al.liberado_em = Date.now();
  return [{ json: { rota: 'gravar', codigo: 200, sets: [{ chave: `cua:${c.id}:${al.token}`, valor: JSON.stringify(al), ttl: 34560000 }],
    resposta: JSON.stringify({ ok: true, token: al.token, nome: al.nome, whatsapp: al.whatsapp || '', link: `${area}?a=${al.token}`, mensagem: msg(al.nome, al.token), zap: al.whatsapp ? `https://wa.me/${al.whatsapp}?text=${encodeURIComponent(msg(al.nome, al.token))}` : '' }) } }];
};
if (P.acao === 'liberar') {
  const nome = cuL(P.nome, 60);
  let zap = String(P.whatsapp || '').replace(/\D/g, '');
  if (zap.length === 10 || zap.length === 11) zap = '55' + zap;
  if (nome.length < 2) return responde(400, { ok: false, erro: 'Diga o nome do aluno.' });
  return libera({ token: cuCodigo(), nome, whatsapp: zap.length >= 12 && zap.length <= 13 ? zap : '', email: '', origem: 'produtor', criado_em: Date.now(), feitas: {}, quizzes: {}, ultima: 0, ultimo_acesso: 0 });
}
if (P.acao === 'liberar_pedido') {
  const al = alunos.find(a => a.token === P.token);
  if (!al) return responde(404, { ok: false, erro: 'Aluno não encontrado.' });
  return libera(al);
}
if (P.acao === 'analise') {
  const liberados = alunos.filter(a => a.liberado);
  if (liberados.length < 1) return responde(200, { ok: true, resumo: 'Ainda não há alunos com acesso. Divulgue a página de vendas e libere os primeiros alunos.', sugestoes: [] });
  const aulas = cuAulas(c);
  const porAula = aulas.map(a => ({ n: a.n, titulo: a.titulo, concluiram: liberados.filter(x => x.feitas && x.feitas[a.n]).length }));
  const quizzes = c.modulos.filter(m => m.quiz.length).map(m => {
    const fez = liberados.filter(x => x.quizzes && x.quizzes[m.n]);
    const erros = m.quiz.map((qq, i) => ({ p: qq.p, erraram: fez.filter(x => (x.quizzes[m.n].erradas || []).includes(i)).length }));
    return { m: m.n, titulo: m.titulo, fizeram: fez.length, media: fez.length ? Math.round(fez.reduce((s, x) => s + x.quizzes[m.n].nota, 0) / fez.length) : null, mais_errada: erros.sort((p, q) => q.erraram - p.erraram)[0] };
  });
  const numeros = { alunos: liberados.length, ativos_7d: liberados.filter(a => Date.now() - (a.ultimo_acesso || 0) < 7 * 864e5).length,
    concluiram: liberados.filter(a => cuProgresso(c, a).feitas === aulas.length).length, certificados: liberados.filter(a => a.certificado).length };
  return [{ json: { rota: 'analise', codigo: 200, sets: [], numeros, texto_ia: `CURSO: ${c.titulo} (${aulas.length} aulas)
ALUNOS COM ACESSO: ${numeros.alunos}
SITUAÇÃO DOS ALUNOS (cada aluno está em UM grupo só; a soma dá ${numeros.alunos}): nunca abriram o curso = ${liberados.filter(a => !a.ultimo_acesso).length} · começaram mas não terminaram = ${liberados.filter(a => a.ultimo_acesso && cuProgresso(c, a).feitas < aulas.length).length} · concluíram todas as aulas = ${numeros.concluiram}
ATIVOS NOS ÚLTIMOS 7 DIAS: ${numeros.ativos_7d} de ${numeros.alunos} · CERTIFICADOS: ${numeros.certificados}
QUANTOS CONCLUÍRAM CADA AULA:
${porAula.map(a => `Aula ${a.n} (${a.titulo}): ${a.concluiram}`).join('\n')}
QUIZZES:
${quizzes.map(q => `Módulo ${q.m} (${q.titulo}): ${q.fizeram} fizeram, média ${q.media === null ? '—' : q.media + '%'}${q.mais_errada && q.mais_errada.erraram ? `; mais errada: "${q.mais_errada.p}" (${q.mais_errada.erraram} erraram)` : ''}`).join('\n')}` } }];
}
