function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê a análise: vale a revisada (todo número citado precisa existir nos dados); se a revisora falhar, a da analista; número que não existe derruba a frase.
const D = $('🔑 Confere a chave do produtor').first().json;
