// Rotina do dia: aluno com o aviso ligado, que parou há 3 dias ou mais e não terminou, recebe "continue de onde parou" (no máximo 1 a cada 3 dias).
const alunos = Object.entries($('🗂️ Lê os alunos (rotina)').first().json || {}).filter(([k]) => /^cua:[a-z0-9-]+:[A-Z0-9]{8}$/.test(k))
