Object.entries($('🗂️ Lê os cursos (rotina)').first().json || {}).filter(([k]) => /^cu:[a-z0-9-]+$/.test(k)).forEach(([k, v]) => { try { const c = JSON.parse(v); cursos[c.id] = c; } catch (e) {} });
