const mapa = modulos.map(m => `Módulo ${m.n}: ${m.titulo} — ${m.objetivo}\n${m.aulas.map(a => `  Aula ${a.n}: ${a.titulo} — ${a.objetivo}`).join('\n')}`).join('\n');
