CURSO: ${plano.titulo} — ${plano.subtitulo}
PLANO COMPLETO:
${mapa}

ESCREVA AGORA O MÓDULO ${m.n} ("${m.titulo}"), com as aulas ${m.aulas.map(a => a.n).join(', ')} (na ordem) e o quiz do módulo.` } }));

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Regras do curso online (as mesmas na criação, na área do aluno, no certificado e no painel do produtor).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const cuT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const cuL = (v, max) => cuT(v, max).replace(/[<>{}]/g, '');
const cuTP = (v, max) => String(v ?? '').replace(/\r/g, '').split(/\n{2,}/).map(p => p.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n\n').replace(/[<>{}]/g, '').slice(0, max);
const cuEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const cuBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const cuNum = v => {
  if (typeof v === 'number') return isFinite(v) && v >= 0 ? Math.round(v * 100) / 100 : null;
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 && n < 1000000 ? Math.round(n * 100) / 100 : null;
};
const cuHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const cuLum = h => cuHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const cuContraste = (a, b) => { const x = cuLum(a), y = cuLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const cuMistura = (a, b, k) => { const x = cuHex(a), y = cuHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores do curso a partir da cor do produtor (contraste garantido: destaque no branco e texto do botão)
function cuTokens(cor) {
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : '#3F51B5';
  let forte = c;
  for (let i = 0; i < 16 && cuContraste(forte, '#FFFFFF') < 4.5; i++) forte = cuMistura(forte, '#000000', 0.12);
  const tinta = cuContraste('#FFFFFF', forte) >= 4.5 ? '#FFFFFF' : '#111111';
  return { cor: c, forte, botao: forte, tinta, fundo: cuMistura(c, '#FFFFFF', 0.95), suave: cuMistura(c, '#FFFFFF', 0.87), linha: cuMistura(c, '#FFFFFF', 0.72), escuro: cuMistura(forte, '#000000', 0.55) };
}
// trava: promessa de ganho, resultado garantido ou R$ que não é o preço do produtor sai da frase
const CU_PROMESSA = /(ganh\w*|fatur\w*|lucr\w*|renda)\s+(de\s+)?(at[eé]\s+)?r\$|fique\s+rico|ficar\s+rico|dinheiro\s+f[aá]cil|renda\s+extra\s+garantid|resultado\s+garantid|garantimos\s+(que|o\s+seu)|100%\s+garantid|sem\s+esfor[cç]o|em\s+\d+\s+dias\s+voc[eê]\s+(vai|ir[aá])\s+(ganhar|faturar)/i;
function cuGuarda(txt, valores, onde, problemas) {
  return String(txt || '').split(/\n{2,}/).map(par => par.split(/(?<=[.!?…])\s+/).filter(f => {
    const vs = (f.match(/R\$\s?\d[\d.]*(?:,\d{1,2})?/g) || []).map(x => Math.round(cuNum(x) * 100)).filter(n => !valores.has(n));
    const prom = CU_PROMESSA.test(f);
    if ((vs.length || prom) && problemas) problemas.push(`${onde}: tirei "${cuT(f, 90)}" (${prom ? 'promessa de ganho/resultado' : 'valor que não é o seu preço'})`);
    return !vs.length && !prom;
  }).join(' ').trim()).filter(Boolean).join('\n\n');
}
