// Monta o curso: plano + aulas revisadas + quizzes + página de vendas + imagens aprovadas + cores + chaves dos avisos no celular (VAPID).
const crypto = require('crypto');
const tenta = f => { try { return f(); } catch (e) { return null; } };
const V = $('🧩 Confere o pedido').first().json, R = $('🧩 Aplica a revisão').first().json, S = $('🧩 Lê as vendas').first().json, plano = $('🧩 Lê o plano').first().json.plano;
