// Grava cada vídeo-aula pronta no curso MAIS RECENTE (lido de novo agora) e diz quantas ficaram prontas.
const st = $('🌐 Pergunta dos vídeos').first().json || {};
let c = null;
try { c = JSON.parse($('📖 Lê o curso (vídeos)').first().json.curso || 'null'); } catch (e) {}
if (!c) return [{ json: { ok: false } }];
const res = st.aulas || {};
let prontos = 0, erros = 0;
c.modulos.forEach(m => m.aulas.forEach(a => {
  const r = res[String(a.n)];
  if (r && r.estado === 'pronto' && r.video) { a.video = r.video; a.capa = r.capa || ''; a.video_s = r.duracao || 0; prontos++; } else if (r && r.estado === 'erro') { a.video_erro = String(r.erro || '').slice(0, 200); erros++; }
}));
const total = c.modulos.reduce((s, m) => s + m.aulas.length, 0);
c.videos = { estado: st.estado === 'pronto' ? (prontos === total ? 'pronto' : 'parcial') : 'demorou', prontos, erros, total, quando: Date.now() };
c.versao = (c.versao || 1) + 1;
let s = {};
try { s = JSON.parse($('📖 Lê o status (vídeos)').first().json.st || '{}'); } catch (e) {}
s.videos = c.videos.estado === 'pronto' ? `${prontos} vídeo-aulas prontas` : `${prontos} de ${total} vídeo-aulas prontas${erros ? ` (${erros} com erro)` : ''}`;
s.videos_prontos = prontos;
return [{ json: { ok: true, curso: JSON.stringify(c), status: JSON.stringify(s), prontos, total } }];

