video,.fig,.cert{width:100%;border-radius:14px;margin:14px 0;background:#000}.fig,.cert{background:none}
.caixa{border-radius:14px;padding:14px 16px;margin:16px 0;background:var(--suave);border-left:5px solid var(--cor)}.caixa ul{margin:6px 0 0 20px}.caixa.ex{background:#FFF7E6;border-color:#B86E00}.caixa.pts{background:#EAF7EF;border-color:#1E7B45}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;padding:12px 20px;border-radius:14px;border:0;background:var(--cor);color:var(--tinta);font:700 16px Inter,sans-serif;text-decoration:none;cursor:pointer}
.btn.sec{background:var(--sup);color:var(--cor);border:1.5px solid var(--linha)}.btn:disabled{opacity:.6}.bts{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}.fim{border-top:1px solid var(--linha);padding-top:16px;margin-top:22px}
.btn:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid var(--cor);outline-offset:2px}
fieldset.pq{border:1px solid var(--linha);border-radius:14px;padding:14px;margin:12px 0}legend{font-weight:700;padding:0 6px}
.op{display:flex;gap:10px;align-items:flex-start;padding:10px;border-radius:10px;cursor:pointer;margin-top:4px}.op input{width:20px;height:20px;margin-top:3px;accent-color:var(--cor);flex:none}
.op.resp{background:#EAF7EF;font-weight:700}fieldset.errado{border-color:#C4320A}fieldset.certo{border-color:#1E7B45}.exp{font-size:15px;color:var(--tx2);margin-top:8px}
.erro{color:#B42318;font-weight:600;min-height:1.2em;margin-top:8px}.dica{background:var(--suave);border-radius:12px;padding:12px;margin-top:12px;font-size:15px}
label{display:block;font-weight:600;margin:12px 0 6px}input#cod{width:100%;font:700 22px ui-monospace,monospace;letter-spacing:6px;text-transform:uppercase;padding:12px;border-radius:12px;border:1.5px solid var(--linha);min-height:52px}
