b = b || {};
const WH = $('🔔 Pedido do aluno (POST)').first().json, h = WH.headers || {};
const ip = String(h['x-real-ip'] || String(h['x-forwarded-for'] || 'sem-ip').split(',')[0]).trim().replace(/[^0-9a-fA-F.:]/g, '').slice(0, 45) || 'sem-ip';
return [{ json: { ...b, id: String(b.id || '').replace(/[^a-z0-9-]/g, '').slice(0, 64) || 'nenhum', token: String(b.token || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8) || 'NENHUM',
