  return grava(aluno, { ok: true, interesse: true, zap: c.venda.whatsapp ? `https://wa.me/${c.venda.whatsapp}?text=${encodeURIComponent(msg)}` : '', checkout: c.venda.checkout || '' });
}
if (!al) return responde(404, { ok: false, erro: 'Código não encontrado. Confira as 8 letras e números que você recebeu.' });
if (!al.liberado) return responde(403, { ok: false, erro: 'Seu acesso ainda não foi liberado. Assim que o pagamento for confirmado, você recebe o código.' });
al.ultimo_acesso = agora;
const aulas = cuAulas(c);
if (P.acao === 'entrar') return grava(al, { ok: true, link: linkAluno(al.token) });
if (P.acao === 'abrir' || P.acao === 'concluir') {
  const n = parseInt(P.aula, 10), a = aulas.find(x => x.n === n);
