ok(st.etapa === 'pronto' && st.modulos === 2 && st.aulas === 4 && st.quizzes === 2, 'O curso não ficou pronto com 2 módulos, 4 aulas e 2 quizzes: ' + JSON.stringify(st).slice(0, 300));
ok(cad.ok && /^[A-Z0-9]{8}$/.test(cad.token || '') && /\/aluno\?a=/.test(cad.link || ''), 'O cadastro grátis devia dar o código de 8 letras e o link: ' + JSON.stringify(cad));
ok(area.includes('"estado":"ok"') && area.includes('"aulas":[') && !area.includes('"certa"'), 'A área da aluna não abriu (ou mostrou a resposta certa do quiz no código da página)');
ok(conc.length === 4 && conc.every(r => r.ok) && conc[3].progresso && conc[3].progresso.pct === 100, 'Concluir as 4 aulas devia dar 100%: ' + JSON.stringify(conc.map(r => r.progresso && r.progresso.pct)));
ok(e1.ok && e1.nota === 0 && e1.passou === false && Array.isArray(e1.itens) && e1.itens.every(i => Number.isInteger(i.certa)), 'Errar o quiz 1 devia dar 0% e mostrar as certas: ' + JSON.stringify(e1).slice(0, 200));
ok(a1.ok && a1.nota === 100 && a1.passou && a1.melhor === 100, 'Acertar o quiz 1 devia dar 100%: ' + JSON.stringify(a1).slice(0, 200));
ok(e2.ok && a2.ok && a2.nota === 100 && a2.progresso && a2.progresso.pode_certificado, 'O quiz 2 devia liberar o certificado: ' + JSON.stringify(a2).slice(0, 200));
ok(cert.ok && /^C[A-Z0-9]{8}$/.test(cert.codigo || '') && /certificado\.jpg$/.test(cert.certificado || ''), 'O certificado não saiu: ' + JSON.stringify(cert));
ok(Number(img.statusCode) === 200 && /image\/jpeg/.test(JSON.stringify(img.headers || {})), 'A imagem do certificado não abriu: ' + img.statusCode);
ok(ver.includes('Certificado válido') && ver.includes('Aluna Teste'), 'A verificação do certificado não confirmou');
ok(lib.ok && /^[A-Z0-9]{8}$/.test(lib.token || '') && (lib.mensagem || '').includes(lib.token), 'O produtor não conseguiu liberar o aluno: ' + JSON.stringify(lib).slice(0, 200));
ok(ana.ok && ana.resumo, 'A análise da IA falhou: ' + JSON.stringify(ana).slice(0, 200));
ok(vendas.includes('Conteúdo do curso') && vendas.includes('Grátis') && vendas.includes('curso-aluno'), 'A página de vendas não veio certa');
const N = p.numeros || {};
ok(N.alunos === 2 && N.concluiram === 1 && N.certificados === 1, 'Números do painel errados: ' + JSON.stringify(N));
ok(N.videos === N.aulas, `As vídeo-aulas não ficaram prontas: ${N.videos} de ${N.aulas} (${JSON.stringify(p.videos)})`);
if (falhas.length) throw new Error(falhas.join(' | '));
return [{ json: { '✅': `Curso pronto em ${st.segundos} s (2 módulos, 4 aulas, 2 quizzes, ${String(st.horas).replace('.', ',')} h) e ${N.videos} vídeo-aulas; aluna cadastrou, concluiu tudo, errou e acertou os quizzes, tirou o certificado ${cert.codigo} (verificado pelo código); produtor liberou outro aluno e pediu a análise`,
  '🛒 vendas': l.link, '📊 painel': l.painel, '🎓 certificado': cert.certificado, '✨ análise': ana.resumo } }];
